    private static void menu(MinecraftClient mc, Screen screen, MatrixStack matrices) { if (listening >= 0 || mapping > 0) return; if (mc.currentScreen!=screen || !read()) return; long handle=mc.getWindow().getHandle(); double[] cx={0}, cy={0}; GLFW.glfwGetCursorPos(handle,cx,cy); int dir=dpad(); if (dir==0) { float mx = Math.abs(ax[6])>0.05f ? ax[6] : dz(ax[0]); float my = Math.abs(ax[7])>0.05f ? ax[7] : dz(ax[1]); if (mx!=0 || my!=0) { int[] ww={1}, wh={1}; GLFW.glfwGetWindowSize(handle,ww,wh); cx[0]=clamp(cx[0]+mx*12,0,ww[0]-1); cy[0]=clamp(cy[0]+my*12,0,wh[0]-1); GLFW.glfwSetCursorPos(handle,cx[0],cy[0]); } } if (dir!=0 && System.currentTimeMillis()-lastNav>160) { if (screen instanceof HandledScreen) moveSlot(mc,(HandledScreen<?>)screen,dir); else moveButton(mc,screen,dir); lastNav=System.currentTimeMillis(); GLFW.glfwGetCursorPos(handle,cx,cy); } double sx=cx[0]*screen.width/Math.max(1,mc.getWindow().getWidth()), sy=cy[0]*screen.height/Math.max(1,mc.getWindow().getHeight()); if (bt[CROSS] && !prev[CROSS]) { if (list(screen)) screen.keyPressed(GLFW.GLFW_KEY_ENTER,0,0); ScreenPad.cross(mc, screen, sx, sy); leftHeld=true; } if (!bt[CROSS] && prev[CROSS] && leftHeld) { screen.mouseReleased(sx,sy,0); leftHeld=false; } if (screen instanceof HandledScreen && bt[L1] && !prev[L1]) { if (!ScreenPad.page(screen, false, sx, sy)) pressBookButton(screen, "prev"); } if (screen instanceof HandledScreen && bt[R1] && !prev[R1]) { if (!ScreenPad.page(screen, true, sx, sy)) pressBookButton(screen, "next"); } if (screen instanceof HandledScreen && bt[SQUARE] && !prev[SQUARE]) ScreenPad.swap(mc, (HandledScreen<?>) screen, sx, sy); if (screen instanceof HandledScreen && bt[TRIANGLE] && !prev[TRIANGLE]) ScreenPad.quick(mc, (HandledScreen<?>) screen, sx, sy); if (bt[CIRCLE] && !prev[CIRCLE]) { screen.keyPressed(GLFW.GLFW_KEY_ESCAPE,0,0); noDropUntil=System.currentTimeMillis()+500; } CursorDraw.plus(matrices, sx, sy); copyPrev(); }
